/**
 * Row-side dispatch streams: {@code arbiter.select()} returns a cursor and the winning strategy's work happens as the
 * consumer pulls rows, long after dispatch returns. Timing the dispatch call would measure the time to open a cursor,
 * not the time to run the strategy, so the elapsed time must be taken when the winning cursor closes. This spec pins
 * that: no observation while the cursor is still streaming, none for a deliberately truncated stream, and exactly one
 * when a completed stream closes. Treating LIMIT-style early close as a full-work sample would systematically make
 * truncated strategies appear faster than they are.
 * <p>
 * The aggregate dispatch site is different — there {@code select()} runs the whole aggregation before returning — and
 * its recording is wired directly around the select call in {@code NativeGroupIteration}.
 */
public class LmdbNativeRowSideCalibrationTest {

	private static final String EX = "http://example.com/";

	// Pin dispatch to the batch rung: every specialized rival must be isolated because the completed tiers all
	// participate in one cost arbiter and may otherwise absorb this deliberately small join.
	private static final String[] DISABLED = {
			LmdbNativeJaninoCodegen.ENABLED_PROPERTY,
			LmdbNativeLeapfrogJoin.ENABLED_PROPERTY,
			"rdf4j.lmdb.parallel.enabled",
			"rdf4j.lmdb.prefixRun.enabled",
			"rdf4j.lmdb.packedFtree.enabled",
			"rdf4j.lmdb.kernelInterpreter.enabled",
			"rdf4j.lmdb.factorizedRows.enabled",
	};

	// The hash join's admission floor assumes production-sized stores; this dataset is deliberately small.
	private static final String MIN_ROWS = LmdbNativeHashJoin.MIN_ROWS_PROPERTY;

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		for (String property : DISABLED) {
			System.setProperty(property, "false");
		}
		System.setProperty(MIN_ROWS, "0");
		LmdbNativeCostCalibration.reset();
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI value = vf.createIRI(EX, "value");
			IRI link = vf.createIRI(EX, "link");
			conn.begin();
			for (int i = 0; i < 300; i++) {
				IRI subject = vf.createIRI(EX, "s" + i);
				conn.add(subject, value, vf.createLiteral(i));
				conn.add(subject, link, vf.createIRI(EX, "s" + ((i + 1) % 300)));
			}
			conn.commit();
		}
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
		for (String property : DISABLED) {
			System.clearProperty(property);
		}
		System.clearProperty(MIN_ROWS);
		LmdbNativeCostCalibration.reset();
	}

	@Test
	public void batchDispatchRecordsCompletedWorkOnlyWhenTheCursorCloses() {
		long before = LmdbNativeCostCalibration.observations(LmdbNativeAttemptMetrics.PATH_BATCH);
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?a ?v ?b WHERE { ?a ex:link ?b . ?a ex:value ?v }";
		try (SailRepositoryConnection conn = repository.getConnection()) {
			try (TupleQueryResult result = conn.prepareTupleQuery(QueryLanguage.SPARQL, query).evaluate()) {
				assertThat(result.hasNext()).isTrue();
				result.next();
				assertThat(LmdbNativeCostCalibration.observations(LmdbNativeAttemptMetrics.PATH_BATCH))
						.as("the cursor is still streaming: its elapsed time is not yet known, so nothing can have "
								+ "been recorded")
						.isEqualTo(before);
			}
			assertThat(LmdbNativeCostCalibration.observations(LmdbNativeAttemptMetrics.PATH_BATCH))
					.as("a deliberately truncated cursor must not charge full predicted work to a partial execution")
					.isEqualTo(before);

			try (TupleQueryResult result = conn.prepareTupleQuery(QueryLanguage.SPARQL, query).evaluate()) {
				while (result.hasNext()) {
					result.next();
				}
				assertThat(LmdbNativeCostCalibration.observations(LmdbNativeAttemptMetrics.PATH_BATCH))
						.as("exhaustion auto-closes the completed cursor and records its final elapsed time")
						.isEqualTo(before + 1L);
			}
			assertThat(LmdbNativeCostCalibration.observations(LmdbNativeAttemptMetrics.PATH_BATCH))
					.as("the surrounding explicit close must not duplicate the exhaustion-time observation")
					.isEqualTo(before + 1L);
		}
	}
}
